import React, { useState } from 'react';
import './SearchDocument.css';
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import SupervisorSidebar from "../components/SupervisorSidebar";

const SearchDocumentPage = () => {
  // Sample document data (replace with real data)
  const [documents, setDocuments] = useState([
    { title: "Machine Learning Trends", status: "approved", type: "report", date: "2024-01-15" },
    { title: "Blockchain Security", status: "pending", type: "proposal", date: "2024-01-10" },
    { title: "Data Privacy Insights", status: "rejected", type: "report", date: "2024-01-05" },
    // Add more documents as needed
  ]);

  // State variables for filters and search query
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedType, setSelectedType] = useState('');
  const [selectedStatus, setSelectedStatus] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Filter documents based on search and filters
  const handleSearch = () => {
    return documents.filter((doc) => {
      return (
          (doc.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
              doc.type.toLowerCase().includes(searchQuery.toLowerCase())) &&
          (selectedType ? doc.type === selectedType : true) &&
          (selectedStatus ? doc.status === selectedStatus : true) &&
          (startDate ? new Date(doc.date) >= new Date(startDate) : true) &&
          (endDate ? new Date(doc.date) <= new Date(endDate) : true)
      );
    });
  };

  return (
      <div className="search-document-container">
        <Navbar />
        <div className="content-wrapper">
          <SupervisorSidebar />

          <div className="search-container">
            <h2>Search Documents</h2>

            {/* Search Bar */}
            <div className="search-bar">
              <input
                  type="text"
                  placeholder="Search by title, keywords, or tags"
                  className="search-input"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
              />
              <button className="btn search-btn" onClick={handleSearch}>Search</button>
            </div>

            {/* Filters Section */}
            <div className="filters-container">
              <h3>Filters</h3>
              <div className="filters">
                <select className="filter" onChange={(e) => setSelectedType(e.target.value)} value={selectedType}>
                  <option value="">Filter by Type</option>
                  <option value="report">Report</option>
                  <option value="thesis">Thesis</option>
                  <option value="proposal">Proposal</option>
                </select>

                <select className="filter" onChange={(e) => setSelectedStatus(e.target.value)} value={selectedStatus}>
                  <option value="">Filter by Status</option>
                  <option value="pending">Pending</option>
                  <option value="approved">Approved</option>
                  <option value="rejected">Rejected</option>
                </select>

                <input
                    type="date"
                    className="filter"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    placeholder="Start Date"
                />
                <input
                    type="date"
                    className="filter"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    placeholder="End Date"
                />
              </div>
            </div>

            {/* Document Results */}
            <div className="results-container">
              <h3>Search Results</h3>
              {handleSearch().length > 0 ? (
                  <ul className="document-list">
                    {handleSearch().map((doc, index) => (
                        <li key={index} className="document-card">
                          <div className="document-title">{doc.title}</div>
                          <div className="document-meta">
                            <span>{doc.type} - {doc.status}</span>
                            <span>Date: {doc.date}</span>
                          </div>
                        </li>
                    ))}
                  </ul>
              ) : (
                  <p>No documents match your search criteria.</p>
              )}
            </div>
          </div>

        </div>
        <Footer />
      </div>
  );
};

export default SearchDocumentPage;
